sys_script_include.script:
var GOACallFlowFromClient = Class.create();
GOACallFlowFromClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    runFlowAction: function () {

        var inputs = {
            submitter_id: this.getParameter('sysparm_submitter_id'),
            ticket: this.getParameter('sysparm_ticket'),
            user_email: this.getParameter('sysparm_user_email'),
            option: this.getParameter('sysparm_option')
        };

		gs.addInfoMessage('This is the script include ' + inputs.submitter_id);

        var result = sn_fd.FlowAPI.getRunner()
            .action('2c70c2403bde3210738bf2d643e45a64')
            .inForeground()
            .withInputs(inputs)
            .run();

        var outputs = result.getOutputs();

        return JSON.stringify({
            status: outputs.status,
            message: outputs.output
        });
    }
});
